CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches (id text PRIMARY KEY, name text NOT NULL, type text NOT NULL DEFAULT 'TOKO', active boolean NOT NULL DEFAULT true, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE categories (name text PRIMARY KEY, position integer NOT NULL DEFAULT 0);
CREATE TABLE profiles (uid text PRIMARY KEY, username text NOT NULL UNIQUE, auth_email text NOT NULL, display_name text NOT NULL, role text NOT NULL CHECK(role IN ('TOKO','TAX','ADMIN')), branch_id text REFERENCES branches(id), active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, uid text NOT NULL REFERENCES profiles(uid), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(uid);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE photos (id uuid PRIMARY KEY, owner_uid text NOT NULL REFERENCES profiles(uid), branch_id text REFERENCES branches(id), object_key text NOT NULL UNIQUE, thumbnail_key text, mime_type text NOT NULL, byte_size bigint NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','READY','DELETED')), upload_group text, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE receipts (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branches(id), owner_uid text NOT NULL REFERENCES profiles(uid), supplier text NOT NULL DEFAULT '', receipt_date date, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('DRAFT','PENDING','NEEDS_CORRECTION','APPROVED','REJECTED')), total numeric(20,4) NOT NULL DEFAULT 0, eliminated boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX receipts_branch_status_date ON receipts(branch_id,status,receipt_date DESC,id);
CREATE INDEX receipts_status_date ON receipts(status,receipt_date DESC,id);
CREATE TABLE receipt_items (id text PRIMARY KEY, receipt_id text NOT NULL REFERENCES receipts(id) ON DELETE CASCADE, position integer NOT NULL, description text NOT NULL, category text NOT NULL, quantity numeric(20,6) NOT NULL DEFAULT 1, unit text NOT NULL DEFAULT '', amount numeric(20,4) NOT NULL, data jsonb NOT NULL DEFAULT '{}', UNIQUE(receipt_id,position));
CREATE TABLE receipt_photos (receipt_id text REFERENCES receipts(id) ON DELETE CASCADE, photo_id uuid REFERENCES photos(id), PRIMARY KEY(receipt_id,photo_id));
CREATE TABLE transactions (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('OCR','LISTRIK','UMUM')), branch_id text REFERENCES branches(id), business_date date, amount numeric(20,4) NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX transactions_kind_branch_date ON transactions(kind,branch_id,business_date DESC,id);
CREATE TABLE master_links (branch_id text REFERENCES branches(id), period text NOT NULL, spreadsheet_id text NOT NULL, data jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(branch_id,period));
CREATE TABLE jobs (id uuid PRIMARY KEY, uid text NOT NULL REFERENCES profiles(uid), kind text NOT NULL, branch_id text REFERENCES branches(id), request_key text NOT NULL, payload_hash text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','NEEDS_REVIEW','CANCELLED')), result jsonb, progress integer NOT NULL DEFAULT 0, error_code text, workflow_run_id text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(uid,kind,request_key));
CREATE INDEX jobs_dispatch ON jobs(status,created_at);
CREATE TABLE job_steps (job_id uuid REFERENCES jobs(id), step_key text NOT NULL, status text NOT NULL, result jsonb, attempts integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(job_id,step_key));
CREATE TABLE outbox (job_id uuid PRIMARY KEY REFERENCES jobs(id), dispatched_at timestamptz, lease_until timestamptz, next_attempt_at timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0);
CREATE TABLE mutations (uid text REFERENCES profiles(uid), action text, request_key text, payload_hash text NOT NULL, result jsonb, PRIMARY KEY(uid,action,request_key));
CREATE TABLE review_claims (receipt_id text PRIMARY KEY REFERENCES receipts(id), uid text REFERENCES profiles(uid), expires_at timestamptz NOT NULL);
CREATE TABLE sheet_mappings (item_id text PRIMARY KEY, receipt_id text, spreadsheet_id text NOT NULL, sheet_id bigint NOT NULL, row_index integer NOT NULL, snapshot jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1);
CREATE TABLE resource_leases (resource text PRIMARY KEY, owner text NOT NULL, generation bigint NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL);
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, uid text, action text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_recent ON audit_events(created_at DESC);
CREATE TABLE auth_rate_limits (key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
